+            Some(true)
+        );
+        let call = serde_json::json!({ "flags": 4, "checkFlags": 1 << 21, "declarations": ["1.215./a.js"] });
+        assert_eq!(settled(call), None);
+        assert_eq!(settled(serde_json::json!({ "flags": 4, "checkFlags": 0, "declarations": ["bad"] })), None);
+    }
