"""Scratch: interleaved instruction/CPU/RSS runs of three builds over the corpora, with an output diff vs main."""
import json, os, re, subprocess, sys, statistics

HERE = os.path.dirname(os.path.abspath(__file__))
C = "/Users/gabe/.cache/caliper/corpora/repos"
CORPORA = [
    ("mantine", f"{C}/mantine/packages/@mantine/core/src", []),
    ("chakra", f"{C}/chakra-ui/packages/react/src", []),
    ("chakra-none", f"{C}/chakra-ui/packages/react/src", ["--collapse-inherited-props", "none"]),
    ("shadcn", f"{C}/shadcn-ui/apps/v4", []),
]
BINS = ["main", "pr", "fix"]
RUNS = int(sys.argv[1]) if len(sys.argv) > 1 else 5
only = sys.argv[2].split(",") if len(sys.argv) > 2 else None


def bad_semantic(diags):
    out = []
    def walk(o):
        if isinstance(o, dict):
            if "code" in o and "severity" in o:
                code = str(o.get("code"))
                if "SEMANTIC_BACKEND" in code and str(o.get("severity")).lower() != "info":
                    out.append((code, o.get("severity")))
            for v in o.values():
                walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
    walk(diags)
    return out


def strip(o):
    if isinstance(o, dict):
        return {k: strip(v) for k, v in o.items() if k != "stats"}
    if isinstance(o, list):
        return [strip(v) for v in o]
    return o


results = {}
for name, src, extra in CORPORA:
    if only and name not in only:
        continue
    for run in range(RUNS):
        for b in BINS:
            out = f"{HERE}/out-{name}-{b}-{run}.json"
            cmd = ["/usr/bin/time", "-l", f"{HERE}/bin-{b}", "extract", "--src", src, "--quiet", "--no-cache",
                   "--load-dependencies", "--json", *extra]
            with open(out, "w") as fh:
                p = subprocess.run(cmd, stdout=fh, stderr=subprocess.PIPE, text=True)
            err = p.stderr
            ins = int(re.search(r"(\d+)\s+instructions retired", err).group(1))
            rss = int(re.search(r"(\d+)\s+maximum resident set size", err).group(1))
            m = re.search(r"([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys", err)
            cpu = float(m.group(2)) + float(m.group(3))
            data = json.load(open(out))
            bad = bad_semantic(data.get("diagnostics", data) if isinstance(data, dict) else data)
            load = os.getloadavg()[0]
            print(f"{name} {b} run{run} exit={p.returncode} ins={ins} cpu={cpu:.2f} rss={rss} bad={len(bad)} load={load:.1f}",
                  flush=True)
            results.setdefault((name, b), []).append(None if (bad or p.returncode) else (ins, cpu, rss))
            if run == 0:
                with open(f"{HERE}/norm-{name}-{b}.json", "w") as fh:
                    json.dump(strip(data), fh, sort_keys=True)
            os.remove(out) if run > 0 else None

print("\nsummary (median over clean runs)")
for (name, b), rows in sorted(results.items()):
    clean = [r for r in rows if r]
    if not clean:
        print(name, b, "no clean runs")
        continue
    print(f"{name:12} {b:5} n={len(clean)} ins={statistics.median(r[0] for r in clean)/1e9:.3f}G "
          f"cpu={statistics.median(r[1] for r in clean):.2f}s rss={statistics.median(r[2] for r in clean)/2**20:.0f}MiB")
for name, *_ in CORPORA:
    if only and name not in only:
        continue
    ref = open(f"{HERE}/norm-{name}-main.json").read()
    for b in ["pr", "fix"]:
        same = open(f"{HERE}/norm-{name}-{b}.json").read() == ref
        print(f"identical {name} {b} vs main: {same}")

